class SQL:
    def __init__(self, names: list[str], columns: list[int]):
        # table -> rowId -> row values. Counter never goes backwards.
        self._tables: dict[str, dict[int, list[str]]] = {n: {} for n in names}
        self._width: dict[str, int] = dict(zip(names, columns))
        self._next_id: dict[str, int] = {n: 1 for n in names}

    def insertRow(self, name: str, row: list[str]) -> None:
        # Real engine would validate width, types, constraints here.
        rid = self._next_id[name]
        self._tables[name][rid] = list(row)
        self._next_id[name] = rid + 1

    def deleteRow(self, name: str, rowId: int) -> None:
        # Tombstone in real MVCC; here just drop. Id is never reused.
        self._tables[name].pop(rowId, None)

    def selectCell(self, name: str, rowId: int, columnId: int) -> str:
        # columnId is 1-based in the problem contract.
        return self._tables[name][rowId][columnId - 1]
